CREATE TABLE IF NOT EXISTS match_runtime (external_id TEXT PRIMARY KEY, match_id TEXT NOT NULL, state TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS arena_audit (id TEXT PRIMARY KEY, at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, match_id TEXT, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS arena_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS server_jobs (server_id TEXT PRIMARY KEY, token TEXT NOT NULL, expires INTEGER NOT NULL, match_id TEXT, external_id TEXT, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS steam_returns (state_hash TEXT PRIMARY KEY, return_path TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS server_tickets (token_hash TEXT PRIMARY KEY, external_id TEXT NOT NULL, config TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS arena_backups (id TEXT PRIMARY KEY, at INTEGER NOT NULL, payload BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS arena_restore_guard (id INTEGER PRIMARY KEY CHECK(id=1));
